package paperwork

import (
 "context"
 "database/sql"
 "encoding/json"
 "errors"
 "io/fs"
 "os"
 "path/filepath"
 "reflect"
 "sort"
 "strings"
)
func copyFile(source,target string)error{info,e:=os.Lstat(source);if e!=nil{return e};if !info.Mode().IsRegular(){return errors.New("Snapshot contains symbolic links or non-regular files")};data,e:=os.ReadFile(source);if e!=nil{return e};if e=os.MkdirAll(filepath.Dir(target),0700);e!=nil{return e};return os.WriteFile(target,data,0600)}
func copyTree(source,target string)error{if e:=os.MkdirAll(target,0700);e!=nil{return e};return filepath.WalkDir(source,func(path string,d fs.DirEntry,e error)error{if e!=nil{return e};if d.Type()&os.ModeSymlink!=0{return errors.New("Snapshot contains symbolic links")};rel,e:=filepath.Rel(source,path);if e!=nil{return e};if d.IsDir(){return os.MkdirAll(filepath.Join(target,rel),0700)};if strings.HasPrefix(d.Name(),".pending-"){return nil};return copyFile(path,filepath.Join(target,rel))})}
func manifestFor(root string)(map[string]string,error){out:=map[string]string{};e:=filepath.WalkDir(root,func(path string,d fs.DirEntry,e error)error{if e!=nil{return e};if d.Type()&os.ModeSymlink!=0{return errors.New("Snapshot contains symbolic links")};if d.IsDir(){return nil};if d.Name()=="manifest.json"{return nil};info,e:=d.Info();if e!=nil{return e};if !info.Mode().IsRegular(){return errors.New("Non-regular snapshot file")};rel,e:=filepath.Rel(root,path);if e!=nil{return e};digest,e:=FileHash(path);if e!=nil{return e};out[filepath.ToSlash(rel)]=digest;return nil});return out,e}
func writeManifest(root string)(map[string]string,error){m,e:=manifestFor(root);if e!=nil{return nil,e};data,e:=json.MarshalIndent(m,"","  ");if e!=nil{return nil,e};e=os.WriteFile(filepath.Join(root,"manifest.json"),append(data,'\n'),0600);return m,e}
func(s *Store)Backup(destination string)(map[string]string,error){if e:=os.MkdirAll(filepath.Dir(destination),0700);e!=nil{return nil,e};if e:=os.Mkdir(destination,0700);e!=nil{return nil,e};dbpath:=filepath.Join(destination,"paperwork.sqlite");if _,e:=s.DB.Exec("VACUUM INTO ?",dbpath);e!=nil{return nil,e};if e:=os.Chmod(dbpath,0600);e!=nil{return nil,e};if e:=copyTree(s.Originals,filepath.Join(destination,"originals"));e!=nil{return nil,e};m,e:=writeManifest(destination);if e!=nil{return nil,e};_,e=VerifySnapshot(destination);return m,e}
func VerifySnapshot(destination string)(map[string]any,error){info,e:=os.Lstat(destination);if e!=nil{return nil,e};if info.Mode()&os.ModeSymlink!=0{return nil,errors.New("Snapshot contains symbolic links")};root,e:=filepath.Abs(destination);if e!=nil{return nil,e};var m map[string]string;if e=readJSON(filepath.Join(root,"manifest.json"),&m);e!=nil{return nil,e};if m==nil{return nil,errors.New("Invalid snapshot manifest")};actual,e:=manifestFor(root);if e!=nil{return nil,e};if !reflect.DeepEqual(m,actual){return nil,errors.New("Snapshot has unlisted, missing or corrupted files")};db,e:=sql.Open("sqlite","file:"+filepath.ToSlash(filepath.Join(root,"paperwork.sqlite"))+"?mode=ro");if e!=nil{return nil,e};defer db.Close();var integrity string;var version int;if e=db.QueryRow("PRAGMA integrity_check").Scan(&integrity);e!=nil{return nil,e};if integrity!="ok"{return nil,errors.New("Invalid SQLite snapshot")};if e=db.QueryRow("PRAGMA user_version").Scan(&version);e!=nil{return nil,e};if version!=1{return nil,errors.New("Unsupported snapshot schema")};rows,e:=db.Query("SELECT id FROM documents");if e!=nil{return nil,e};defer rows.Close();for rows.Next(){var id string;if e=rows.Scan(&id);e!=nil{return nil,e};if !identityRE.MatchString(id)||m["originals/"+id]!=id{return nil,errors.New("Original does not match its canonical SHA-256 identity")}};if e=rows.Err();e!=nil{return nil,e};return map[string]any{"verified":true,"files":len(m)},nil}
func noteFiles(ctx context.Context,space Space)([]string,error){all,e:=space.Files(ctx);if e!=nil{return nil,e};out:=[]string{};for _,p:=range all{if strings.HasSuffix(p,".md")&&!strings.HasPrefix(p,"Library/"){out=append(out,p)}};sort.Strings(out);return out,nil}
func(s *Store)BackupWithNotes(ctx context.Context,space Space,destination string)(map[string]any,error){initial,e:=noteFiles(ctx,space);if e!=nil{return nil,e};if _,e=s.Backup(destination);e!=nil{return nil,e};if e=os.Remove(filepath.Join(destination,"manifest.json"));e!=nil{return nil,e};revisions:=map[string]string{};for _,path:=range initial{if !safePath(path){return nil,errors.New("Unsafe note path")};content,etag,e:=space.Read(ctx,path);if e!=nil{return nil,e};if content==nil||etag==""{return nil,errors.New("Cannot establish note revision")};target:=filepath.Join(destination,"notes",filepath.FromSlash(path));if e=os.MkdirAll(filepath.Dir(target),0700);e!=nil{return nil,e};if e=os.WriteFile(target,[]byte(*content),0600);e!=nil{return nil,e};revisions[path]=etag};for _,path:=range initial{_,etag,e:=space.Read(ctx,path);if e!=nil{return nil,e};if etag!=revisions[path]{return nil,errors.New("Notes changed during backup; retry with a new destination")}};final,e:=noteFiles(ctx,space);if e!=nil{return nil,e};if !reflect.DeepEqual(initial,final){return nil,errors.New("Note list changed during backup")};if _,e=writeManifest(destination);e!=nil{return nil,e};return VerifySnapshot(destination)}
func Restore(snapshot,destination,spaceDestination string)(map[string]any,error){snapshot,e:=filepath.Abs(snapshot);if e!=nil{return nil,e};destination,e=filepath.Abs(destination);if e!=nil{return nil,e};if _,e=VerifySnapshot(snapshot);e!=nil{return nil,e};if _,e=os.Lstat(destination);!os.IsNotExist(e){return nil,errors.New("Restore destination must be new")};if spaceDestination!=""{spaceDestination,e=filepath.Abs(spaceDestination);if e!=nil{return nil,e};if _,e=os.Lstat(spaceDestination);!os.IsNotExist(e){return nil,errors.New("Space destination must be new")}};if e=os.MkdirAll(filepath.Dir(destination),0700);e!=nil{return nil,e};temp,e:=os.MkdirTemp(filepath.Dir(destination),".paperwork-restore-");if e!=nil{return nil,e};defer os.RemoveAll(temp);stage:=filepath.Join(temp,"library");if e=copyTree(snapshot,stage);e!=nil{return nil,e};if _,e=VerifySnapshot(stage);e!=nil{return nil,e};notes:=filepath.Join(stage,"notes");if _,e=os.Stat(notes);e==nil&&spaceDestination!=""{if e=copyTree(notes,spaceDestination);e!=nil{return nil,e};if e=os.RemoveAll(notes);e!=nil{return nil,e}};if e=os.Remove(filepath.Join(stage,"manifest.json"));e!=nil{return nil,e};if e=os.Rename(stage,destination);e!=nil{return nil,e};var space any;if spaceDestination!=""{space=spaceDestination};return map[string]any{"restored":true,"library":destination,"space":space},nil}
